<?php $this->layout('default'); use Moves\Services\CmsAudit; use Moves\Services\CmsQuery as Q; use Moves\Support\CmsView as V; $filters = ['q' => V::queryString('q')]; $result = CmsAudit::listing($filters, V::queryPage(), 30);
$attention = "event_type REGEXP 'denied|suspended|failed|deleted|inactivated|canceled'"; ?>
<?php $this->start('actions'); ?><span class="cms-pill"><?= (int) $result['total'] ?> registro(s)</span><?php $this->stop(); ?>
<?= V::kpis([['pages', 'Total', (string) Q::value('SELECT COUNT(*) FROM cms_audit_logs'), 'registros preservados'], ['alert', 'Atenção', (string) Q::value("SELECT COUNT(*) FROM cms_audit_logs WHERE {$attention}"), 'recusas, suspensões e exclusões'], ['key', 'Logins', (string) Q::value("SELECT COUNT(*) FROM cms_audit_logs WHERE event_type='cms.login'"), 'acessos ao CMS'], ['clock', 'Últimas 24h', (string) Q::value('SELECT COUNT(*) FROM cms_audit_logs WHERE created_at >= NOW() - INTERVAL 1 DAY'), 'atividade recente']]) ?>
<section class="cms-list"><?= V::listHead('Eventos encontrados', 'Sem senhas, tokens ou dados financeiros', V::searchForm('Evento, registro ou e-mail')) ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum evento encontrado.') ?><?php else: ?><div class="cms-log"><?php foreach ($result['rows'] as $l): $warn = preg_match('/denied|suspended|failed|deleted|inactivated|canceled/', $l['event_type']) === 1; ?><details><summary><span class="cms-level cms-level-<?= $warn ? 'warn' : 'info' ?>"><?= $warn ? 'Atenção' : 'Aviso' ?></span><span class="cms-log-main"><strong><?= V::e($l['event_type']) ?></strong><small><code><?= V::e($l['resource_type']) ?> <?= V::e($l['resource_id']) ?></code> · <?= V::e($l['actor_email'] ?? 'Sistema') ?> · <?= V::date($l['created_at']) ?></small></span></summary><pre><?= V::e($l['changes_json'] ?? 'Sem detalhes.') ?></pre></details><?php endforeach; ?></div><?= V::pager($result) ?><?php endif; ?></section>
